  });
}
if (data.pv.inkomstenVanuitAanvraag?.uitkeringTypes?.length > 0) {
  uitkeringen = data.pv.inkomstenVanuitAanvraag.uitkeringTypes.map(uitkeringType => {
const uitkeringMap = {
